/*---------------------------------Funktionen--------------------------*/
/*Funktion zum formatieren einer Liste von [x=1, x=2, ...] zu [1, 2, ...]*/
liste_formatieren(l):=block(
    [ergebnis:[], i],
    for i:1 thru length(l) do (
        ergebnis:append(ergebnis, [rhs(l[i])])
    ),
    ergebnis
);

/*Dieser Funktion übergibt man eine Liste von NS der ersten Ableitung "ns_df1_list". Die NS werden in die zweite Ableitung eingefügt und ihre Werte in der Ergebnisliste zurückgegeben.*/
ns_df1_in_df2(l):=block(
    [resultList:[], i],
    for i:1 thru length(l) do (
        resultList:append(resultList, [diff2_h(l[i])])
    ),
    resultList
);

/*Findet das Kriterium des Sattelpunktes (h''(t)=0) aus listReference und loescht entsprechend seines Indexes die Referenz des Sattelpunktes aus listReference und dessen x-Wert aus listValue.*/
loesch_sattelpunktreferenz_und_Wert_von_sattelpunkt (listValue, listReference):=block(
    [i, idx],
    idx:100,
    for i:1 thru length(listReference) do (
        if listReference[i] = 0 then idx:i
    ),
    if idx # 100 then (
        listReference:delete(listReference [idx], listReference),
        listValue:delete(listValue [idx], listValue)
    ),
[listValue, listReference]
);

/*Durchsucht die Referenzliste nach dem Kriterium für einen HP (h''(t)<0), speichert dessen Index und gibt aus der Werteliste mittels dieses Indexes den Wert des HP zurück. Dient dazu damit ein Sattelpunkt nicht für eine Extremstelle gehalten wird.*/
finde_HP_xWert(listValue, listReference):=block(
    [i, idx_HP, HP_Reference, HP_Value],
    HP_Reference:apply(min, listReference),
    for i:1 thru length(listReference) do(
        if listReference[i] = HP_Reference then idx_HP:i
    ),
    return (listValue[idx_HP])
);

/*Funktion rundet Elemente einer übergebenen Liste auf zwei Nachkommastellen.
[12,12.1,12.2,12.994,12.995] -> [12.0,12.1,12.2,12.99,13.0]*/
runden(list):=block(
    [i, ergebnisliste:[]],
    for i:1 thru length(list) do (
        element:float(round(list[i]*100)/100),
        ergebnisliste:append(ergebnisliste, [element])
    ),
    return (ergebnisliste)
);

/*--------------------------------------------------------------------*/

/*----------Test------------*/
/*h(t):=-7*t^3+49*t^2+23*t+51;*/
/*diff1_h(t):=21*t^2+98*t+23;*/
/*diff2_h(t):=42*t+98;*/
/*[x=-4.42,y=1510.1]*/
/*[x=148270607/33554432,y=57050056605153579661566537/37778931862957161709568]*/
/*--------------------------*/
a:rand_with_step(-10, 0, 1);
b:rand_with_step(1, 50, 3);
c:rand_with_step(1, 50, 2);
d:rand_with_step(20, 100, 1);

h(t):=a*t^3+b*t^2+c*t+d;
diff1_h(t):=3*a*t^2+2*b*t+c;                              /*Erste Ableitung von h(t)*/
diff2_h(t):=2*3*a*t+2*b;                                  /*Zweite Ableitung von h(t)*/


/*--------------------Werte für Aufgabenstellung------------------------*/

S_yWert:h(0);                                   /*y-Wert von Schnittpunkt mit y-Achse*/
NS_xWert:rhs(realroots(h(t)=0)[1]);             /*x-Wert von Schnittpunkt mit x-Achse*/
sekunden:1+rand(floor(NS_xWert));               /*Wert für Aufgabenstellung*/


/*----------------------Aufgabenteil b) ---------------------------------*/

ns_diff1_list_UNFORMATIERT:realroots(diff1_h(t));             /*Liste mit NS von h'(t)*/
ns_diff1_list:liste_formatieren(ns_diff1_list_UNFORMATIERT);  /*Liste mit NS von h'(t) formatiert*/
diff2_list:ns_df1_in_df2(ns_diff1_list);                      /*Liste von h''(NS_diff1)*/
res:loesch_sattelpunktreferenz_und_Wert_von_sattelpunkt(ns_diff1_list, diff2_list);
ns_diff1_list:first(res);
diff2_list: second(res);
HP_xWert:finde_HP_xWert(ns_diff1_list, diff2_list);           /*x-Wert des HP von h(t)*/
HP_yWert:h(HP_xWert);                                         /*y-Wert des HP von h(t)*/

ergebnisliste_ungerundet:[HP_xWert, HP_yWert];
ergebnisliste_gerundet:runden(ergebnisliste_ungerundet);

tans_ungerundet:[x=ergebnisliste_ungerundet[1], y=ergebnisliste_ungerundet[2]];
tans_gerundet:[x=ergebnisliste_gerundet[1], y=ergebnisliste_gerundet[2]];


/*----------------------------------Validierungsfunktion--------------------------------*/

anzahl_signifikante_nachkommastelle(d):=block(
    [s,nachkommastellen],
    s:string(d),
    nachkommastellen:split(s, ".")[2],
    nachkommastellen_list:charlist(nachkommastellen),
    nachkommastellen_list_length:length(nachkommastellen_list),
    if nachkommastellen_list_length = 0 then
        return (0)
    elseif nachkommastellen_list_length = 1 and nachkommastellen_list[1] = "0" then
        return (0)
    elseif nachkommastellen_list_length > 1 then
    return (nachkommastellen_list_length)
);


entfernePunktUndLetzteZiffer(d):=block(
    [dAlsString, dAlsList, dOhnePunkt, dOhnePunktUndLetzteZiffer:[]],
    dAlsString:string(d),
    dAlsList:charlist(dAlsString),
    dOhnePunkt:delete(".", dAlsList),
    for i:1 thru length(dOhnePunkt)-1 do (
        dOhnePunktUndLetzteZiffer:append(dOhnePunktUndLetzteZiffer, [dOhnePunkt[i]])
    ),
    return (dOhnePunktUndLetzteZiffer)
);


is_fraction(zahl) := block(
    zahl_betrag:abs(zahl),
    (not integerp(zahl_betrag)) and
    (not floatnump(zahl_betrag)) and
    (op(zahl_betrag) = "/")
);


validate(ans, tans) := block(
    [anz_nk_ans, anz_nk_tans,
        nachkommastellen_ans,
        nachkommastellen_tans,
        nachkommast_letzteZiffer_ans, nachkommast_letzteZiffer_tans,
        vorkommastellen_ans, vorkommastellen_tans,
        alleZiffernAusserLetzte_ans, alleZiffernAusserLetzte_tans, ergebnis:"ist korrekt."],
    if integerp(ans) and integerp(tans) then (
        if is(equal(ans, tans)) then (
            return (ergebnis)
        )
        else (
            ergebnis:"ist nicht korrekt.",
            return (ergebnis)
        )
    )
    else if integerp(ans) and floatnump(tans) then (
        vorkommastellen_tans:split(string(tans), ".")[1],
        nachkommastellen_tans:[split(string(tans), ".")[2]],
        if is(equal(string(ans), vorkommastellen_tans)) and length(nachkommastellen_tans) = 1 and nachkommastellen_tans[1] = "0" then (
            return (ergebnis)
        )
        else (
            ergebnis:"ist nicht korrekt.",
            return (ergebnis)
        )
    )
    else if floatnump(ans) and integerp(tans) then (
        vorkommastellen_ans:split(string(ans), ".")[1],
        nachkommastellen_ans:[split(string(ans), ".")[2]],
        if is(equal(string(tans), vorkommastellen_ans)) and length(nachkommastellen_ans) = 1 and nachkommastellen_ans[1] = "0" then (
            return (ergebnis)
        )
        else (
            ergebnis:"ist nicht korrekt.",
            return (ergebnis)
        )
    )
    else if (is_fraction(ans) and floatnump(tans)) or (floatnump(ans) and is_fraction(tans)) then (
        if is_fraction(ans) then ans:round(ans*100)/100.0,
        if is_fraction(tans) then tans:round(tans*100)/100.0,
        if is(equal(ans, tans)) then (
        return (ergebnis)
        )
        else (
            ergebnis:"ist nicht korrekt.",
            return (ergebnis)
        )
    )
    else if is_fraction(ans) and is_fraction(tans) then(
        if is(equal(ans, tans)) then (
            return (ergebnis)
        )
        else (
            ergebnis:"ist nicht korrekt.",
            return (ergebnis)
        )
    )
    else if floatnump(ans) and floatnump(tans) then (
        if is(equal(ans, tans)) then (
            return (ergebnis)
        )
        else (
            vorkommastellen_ans:split(string(ans), ".")[1],
            vorkommastellen_tans:split(string(tans), ".")[1],
            anz_nk_ans: anzahl_signifikante_nachkommastelle(ans),
            anz_nk_tans:anzahl_signifikante_nachkommastelle(tans),
            if vorkommastellen_ans = vorkommastellen_tans and anz_nk_ans # anz_nk_tans then (
                ergebnis:"hat falsche Anzahl an Nachkommastellen.",
                return (ergebnis)
            )
            else (
                nachkommast_letzteZiffer_ans: last(charlist(string(ans))),
                nachkommast_letzteZiffer_tans:last(charlist(string(tans))),
                alleZiffernAusserLetzte_ans:entfernePunktUndLetzteZiffer(ans),
                alleZiffernAusserLetzte_tans:entfernePunktUndLetzteZiffer(tans),
                if is(equal(alleZiffernAusserLetzte_ans, alleZiffernAusserLetzte_tans)) and nachkommast_letzteZiffer_ans # nachkommast_letzteZiffer_tans then (
                    ergebnis:" ist falsch gerundet.",
                    return (ergebnis)
                )
                else (
                    ergebnis:"ist nicht korrekt.",
                    return (ergebnis)
                )
            )
        )
    )
);
